import json, sys
sys.path.insert(0, 'tmp')
import ref

doc = json.load(open('tmp/fail_32.json'))
print('order:', doc['order'])
ixps, rib, priors, declared, order_pairs, queries = ref.validate(doc)
print('validate OK')
agg = {}
for p, c in rib:
    q = ref.norm(p, ixps)
    if len(q) < 2 or len(set(q)) != len(q): continue
    t = tuple(q)
    agg[t] = agg.get(t, 0) + c
final, rounds, links = ref.peel_ref(agg)
core = sorted(k for k in links if k not in rounds)
print('core:', core)
print('order sorted:', sorted(order_pairs))
try:
    assert sorted(order_pairs) == core and len(order_pairs) == len(core)
    print('order matches core')
except AssertionError:
    print('ORDER MISMATCH')
occs, pos = ref.build_occs(final, core)
scopes = {}
for e in core:
    sc = {e}
    for (p, w, i) in occs[e]:
        if i > 0:
            sc.add(ref.canon(p[i-1], p[i]))
        if i + 2 < len(p):
            sc.add(ref.canon(p[i+1], p[i+2]))
    scopes[e] = sc
for e in core:
    print(e, sorted(scopes[e]))
try:
    ref.check_width(core, scopes, order_pairs)
    print('width OK')
except ref.Invalid:
    print('WIDTH FAIL in ref')
EOF
python3 tmp/dbg3.py
